        function detectIntent(message) {
            const lowerMessage = message.toLowerCase();
            
            if (/\b(hi|hello|hey|greetings)\b/.test(lowerMessage)) return 'greetings';
            if (/\b(schedule|appointment|book|booking|meeting|calendar)\b/.test(lowerMessage)) return 'scheduling';
            if (/\b(price|pricing|cost|plan|subscription|pay|payment)\b/.test(lowerMessage)) return 'pricing';
            if (/\b(issue|problem|bug|error|help|technical|support|fix|broken)\b/.test(lowerMessage)) return 'technical';
            if (/\b(feature|features|capability|what can|offer|do you)\b/.test(lowerMessage)) return 'features';
            if (/\b(thank|thanks|thx|appreciate)\b/.test(lowerMessage)) return 'thanks';
            if (/\b(bye|goodbye|see you|later|quit|exit)\b/.test(lowerMessage)) return 'goodbye';
            
            return 'default';
        }

